/**
 * Permission names from specs/authorization/permissions.yaml. Empty in M0 (the matrix arrives in PR-M1).
 *
 * @maxItems 200
 */
export type Permissions = string[];
/**
 * Which dashboard family the principal lands on.
 */
export type Persona = "admin" | "tenant";
export type Principalid = string;
/**
 * Fixture role (approved G0 access model; DR-019). Permissions per role are fixed in specs/authorization/permissions.yaml (PR-M1).
 */
export type Role =
  | "PORTFOLIO_ADMIN"
  | "REGIONAL_ADMIN"
  | "MALL_MANAGER"
  | "LEASING_MANAGER"
  | "FITOUT_MANAGER"
  | "TENANT_COMPANY_ADMIN"
  | "TENANT_LEASE_CONTACT";
export type Sessionexpiresat = string;

/**
 * The signed-in principal returned by GET /api/v1/me and POST /api/v1/auth/dev/sign-in (ARCH-R077). The client uses it only for presentation; authorization is enforced server-side (ARCH-R046). Business keys in grants are provisional until CF-1 confirms them against the seed (ARCH-R078). Bootstrap contract, frozen by CF-0.
 */
export interface PrincipalV1 {
  displayName: Displayname;
  grants: Grants;
  permissions: Permissions;
  persona: Persona;
  principalId: Principalid;
  role: Role;
  sessionExpiresAt: Sessionexpiresat;
}
